INSERT INTO educations (institution, degree, period, gpa, thesis, relevant_courses, achievements, lang) VALUES ('Universitas Islam Negeri Sunan Kalijaga Yogyakarta', 'S1 Matematika', 'September 2022 – Maret 2026', '3.54/4.00', 'Analisis Risiko Portofolio Saham Menggunakan Value at Risk dengan Pendekatan Extreme Value Theory dengan Studi Kasus Saham Subsektor Perbankan Periode 1 Mei 2019 – 31 Mei 2025', 'Analisis Data, Analisis Multivariat, Analisis Regresi Terapan, Basis Data, Komputasi Statistika, Analisis Data Kategorik, Analisis Runtun Waktu, Kapita Selekta Statistika, Pengantar Matematika Aktuaria', '{"Penerima Beasiswa Bank Indonesia Periode 2024 dan 2025","Peneliti dan Presenter dalam International Conference on Religion, Science and Education 2025","Peneliti dan Presenter dalam 2nd Forstat International Conference 2026","Juara 2 Olimpiade Matematika Tingkat Nasional, University ID Educational Platform"}', 'id');
INSERT INTO educations (institution, degree, period, gpa, thesis, relevant_courses, achievements, lang) VALUES ('State Islamic University Sunan Kalijaga Yogyakarta', 'Bachelor of Mathematics', 'September 2022 – March 2026', '3.54/4.00', 'Stock Portfolio Risk Analysis Using Value at Risk with Extreme Value Theory Approach: A Case Study of Banking Subsector Stocks for the Period May 1, 2019 – May 31, 2025', 'Data Analysis, Multivariate Analysis, Applied Regression Analysis, Database, Statistical Computing, Categorical Data Analysis, Time Series Analysis, Capita Selecta of Statistics, Introduction to Actuarial Mathematics', '{"Bank Indonesia Scholarship Grantee Period 2024 and 2025","Researcher and Presenter at International Conference on Religion, Science and Education 2025","Researcher and Presenter at 2nd Forstat International Conference 2026","2nd Place in National Mathematics Olympiad, University ID Educational Platform"}', 'en');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Staff Seksi Verifikasi dan Akuntansi', 'KPPN A1 Magelang', 'April 2026 – Juli 2026', '{"Membantu menyelesaikan 8 translasi Laporan Keuangan BUMD ke Kertas Kerja Excel","Membuat materi presentasi untuk sosialisasi ke Satuan Kerja","Mengembangkan aplikasi untuk penilaian ketepatan pengiriman Laporan Pertanggungjawaban Bendahara Satuan Kerja"}', 'work', 'id');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Staff Multimedia', 'UPT. PTIPD UIN Sunan Kalijaga Yogyakarta', 'Januari 2025 – Desember 2025', '{"Membuat konten visual yang menarik untuk akun media sosial resmi UPT. PTIPD","Membantu dokumentasi kegiatan yang diselenggarakan oleh UPT. PTIPD","Membuat konten untuk website resmi UPT. PTIPD yang meningkatkan traffic website"}', 'work', 'id');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Asisten Instruktur', 'ITTC UIN Sunan Kalijaga Yogyakarta', 'Februari 2025 – Maret 2025', '{"Menyiapkan serta menyusun materi pembelajaran, slide presentasi, dan modul praktik laboratorium","Memberikan dukungan teknis secara one-on-one bagi peserta yang mengalami kendala","Memelihara dan memastikan peralatan serta perangkat lunak laboratorium berfungsi dengan baik"}', 'work', 'id');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Verification and Accounting Section Staff', 'KPPN A1 Magelang', 'April 2026 – July 2026', '{"Assisted in completing 8 translations of BUMD Financial Reports to Excel Working Papers","Created presentation materials for socialization to Work Units","Developed an application for assessing the timeliness of the submission of the Work Unit Treasurer''s Accountability Report"}', 'work', 'en');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Multimedia Staff', 'UPT. PTIPD UIN Sunan Kalijaga Yogyakarta', 'January 2025 – December 2025', '{"Created engaging visual content for UPT. PTIPD official social media accounts","Assisted with documentation of activities organized by UPT. PTIPD","Created content for the UPT. PTIPD official website which increased website traffic"}', 'work', 'en');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Instructor Assistant', 'ITTC UIN Sunan Kalijaga Yogyakarta', 'February 2025 – March 2025', '{"Prepared and compiled learning materials, presentation slides, and laboratory practice modules","Provided one-on-one technical support for participants experiencing difficulties","Maintained and ensured laboratory equipment and software functioned properly"}', 'work', 'en');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Wakil Ketua', 'Himpunan Mahasiswa Program Studi Matematika', 'Desember 2023 – Desember 2024', '{"Memimpin koordinasi antar divisi dalam menjalankan 3 program kerja besar","Menjadi penghubung antara mahasiswa dan program studi dalam menyampaikan aspirasi","Mengevaluasi program kerja yang berhasil meningkatkan partisipasi mahasiswa hingga 50% dibanding periode sebelumnya"}', 'organization', 'id');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Staff Media dan Informasi Kreatif', 'Generasi Baru Indonesia (GenBI)', 'Juli 2024 – Maret 2025', '{"Membuat dan merancang konten untuk media sosial GenBI UIN Sunan Kalijaga","Membantu pengelolaan dokumentasi setiap kegiatan yang dilaksanakan","Membuat materi visual (poster, pamflet, banner) untuk setiap kegiatan komunitas"}', 'organization', 'id');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Staff Media dan Informasi', 'HMPS Matematika', 'Desember 2022 – Desember 2023', '{"Mengelola akun media sosial himpunan dari membuat konten hingga menjadwalkan unggahan","Membuat desain poster dan dokumentasi acara untuk kebutuhan publikasi kegiatan himpunan","Menyebarkan informasi program kerja ke mahasiswa melalui media sosial dan grup komunikasi"}', 'organization', 'id');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Vice Chairman', 'Mathematics Study Program Student Association', 'December 2023 – December 2024', '{"Led coordination between divisions in carrying out 3 major work programs","Acted as a liaison between students and the study program in conveying aspirations","Evaluated work programs which successfully increased student participation by up to 50% compared to the previous period"}', 'organization', 'en');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Creative Media and Information Staff', 'New Generation of Indonesia (GenBI)', 'July 2024 – March 2025', '{"Created and designed content for GenBI UIN Sunan Kalijaga social media","Assisted in managing documentation for every activity carried out","Created visual materials (posters, pamphlets, banners) for all community activities"}', 'organization', 'en');
INSERT INTO experiences (role, organization, period, description, type, lang) VALUES ('Media and Information Staff', 'Mathematics HMPS', 'December 2022 – December 2023', '{"Managed association social media accounts, from creating content to scheduling posts","Created poster designs and event documentation for association event publication needs","Disseminated work program information to students through social media and communication groups"}', 'organization', 'en');
