INSERT INTO projects (title, description, images, tags, repo_url, demo_url, drive_url, lang) VALUES ('Aplikasi Penilaian Laporan', 'Sebuah aplikasi yang dikembangkan untuk menilai ketepatan pengiriman laporan pertanggungjawaban bendahara satuan kerja.', '{"https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&q=80&w=800","https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&q=80&w=800"}', '{"Google Apps Script","Data Processing","Automation"}', 'https://github.com/umarsodiq', 'https://example.com/demo1', NULL, 'id');
INSERT INTO projects (title, description, images, tags, repo_url, demo_url, drive_url, lang) VALUES ('Analisis Risiko Portofolio Saham (Skripsi)', 'Analisis risiko portofolio saham menggunakan Value at Risk (VaR) dengan pendekatan Extreme Value Theory (EVT). Studi kasus pada saham subsektor perbankan periode Mei 2019 hingga Mei 2025.', '{"https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&q=80&w=800"}', '{"R","Data Analysis","Finance","Statistics"}', NULL, NULL, 'https://drive.google.com', 'id');
