INSERT INTO profiles (about_me, lang) VALUES ('Lulusan S1 Matematika UIN Sunan Kalijaga Yogyakarta dengan konsentrasi di statistika, memiliki kemampuan analisis data dan minat mendalam pada Artificial Intelligence. Senang mempelajari hal baru dan berorientasi pada detail, serta terbiasa bekerja secara adaptif dalam lingkungan yang dinamis dan penuh tantangan. Memiliki keterampilan dalam analisis dan visualisasi data, pengolahan data, desain grafis, serta kerja tim dan organisasi. Saat ini sedang mencari peluang di Program Pemagangan Nasional untuk mengembangkan kompetensi sekaligus memberikan kontribusi nyata.', 'id');
INSERT INTO profiles (about_me, lang) VALUES ('Mathematics graduate from UIN Sunan Kalijaga Yogyakarta concentrating in statistics, possessing data analysis skills and a deep interest in Artificial Intelligence. Enjoys learning new things and is detail-oriented, as well as accustomed to working adaptively in a dynamic and challenging environment. Has skills in data analysis and visualization, data processing, graphic design, as well as teamwork and organization. Currently seeking opportunities in the National Internship Program to develop competencies while making a real contribution.', 'en');
